select bpr.id
from bill_pay_record bpr
left join bill_record br on bpr.bill_record_id = br.id
where br.org_id = #{query.orgId}
AND bpr.id in (
    select behr.handled_record_id
    from bill_exception_handle_record behr
    left join bill_exception_handle_detail_record behdr on behr.id = behdr.bill_handle_record_id
    where behr.operate_type = 0 and date_format(behr.crt_time, '%Y-%m') > #{query.queryDate}
    group by behr.handled_record_id
)
and date_format(bpr.crt_time, '%Y-%m') = #{query.queryDate}
and date_format(br.crt_time, '%Y-%m') = #{query.queryDate}

    AND br.org_id = #{query.orgId};


